/**
 * Print real renderer output for the README.
 *
 * The samples in a README are the part most likely to drift from the code, so
 * they are generated by the same functions the plugin calls rather than typed
 * by hand. Run: `node test/samples.mjs`.
 *
 * @module dsh-folderwatch/test/samples
 */

import { renderArm, renderCheck, renderEvents, renderList, renderNotification, renderRemoval } from '../lib/format.js'

const status = {
  id: 'reports',
  root: '/work/shop/reports',
  label: 'reports',
  files: 12,
  directories: 3,
  watchKind: 'recursive',
  pattern: '**/*.json',
  ignore: ['node_modules', '.git'],
  mode: 'wake',
  once: false,
  deliveries: 2,
  deliveredEvents: 7,
  suppressedEvents: 4,
  pending: 0,
  state: 'running',
  lastDeliveryAt: new Date(Date.now() - 90_000).toISOString(),
  truncatedSnapshot: false,
  unreadable: [],
}

const diff = {
  created: [{ path: '/work/shop/reports/run-42.json', size: 18_432 }],
  changed: [{ path: '/work/shop/reports/latest.json', size: 18_432 }],
  deleted: [{ path: '/work/shop/reports/run-41.json', size: 0 }],
}

const batch = { diff, suppressed: 4, truncated: false }

console.log('=== renderNotification ===')
console.log(renderNotification({ ...status, prompt: 'Read the new report and summarise what failed.' }, batch, { at: '14:02:11' }))
console.log('\n=== renderArm ===')
console.log(renderArm(status))
console.log('\n=== renderList ===')
console.log(renderList([status, { ...status, id: 'inbox', label: undefined, root: '/work/shop/inbox', state: 'stopped', pattern: undefined, pending: 3, deliveries: 0, lastDeliveryAt: undefined }], { now: Date.now() }))
console.log('\n=== renderCheck ===')
console.log(renderCheck(status, { diff, events: 3, suppressed: 4 }))
console.log('\n=== renderCheck (quiet) ===')
console.log(renderCheck(status, { diff: { created: [], changed: [], deleted: [] }, events: 0, suppressed: 0 }))
console.log('\n=== renderRemoval ===')
console.log(renderRemoval(status))
console.log('\n=== renderEvents ===')
console.log(renderEvents(diff).join('\n'))
